from pathlib import Path
import base64

ROOT=Path(__file__).resolve().parents[2]/'docs/setup/images'

def desk_image(slug):
    if (ROOT/f"{slug}-desk.svg").exists():
        return
    raise FileNotFoundError(f"Missing packaged Desk illustration: {ROOT / (slug + '-desk.svg')}")

def desk_steps(slug):
    desk_image(slug)
    if slug=='umi':
        return '<ol class="step-list"><li>In Franka Desk, open <strong>Settings → End-effector</strong> (1).</li><li>Select <strong>Franka Hand</strong> (2), then click <strong>Apply</strong> (3). No configuration file is needed.</li><li>After changing fingertips, clear the hand and click <strong>Homing</strong> (4). The fingers move during homing.</li></ol><figure><a href="images/umi-desk.svg"><img src="images/umi-desk.svg" alt="Franka Desk: End-effector, Franka Hand, Apply and Homing circled"></a><figcaption>UMI uses the native Franka Hand configuration. Click the image to enlarge.</figcaption></figure>'
    file={'robotiq':'robotiq_2f85.json','sharpa':'sharpa_angled.json'}[slug]
    return f'<p>Download <a href="https://github.com/Stanford-TML/cloak/blob/main/deployment/endeffector_configs/{file}">{file}</a> from <code>deployment/endeffector_configs/</code> in the repository to the computer where you use Franka Desk. On GitHub, use the file’s Download raw file button.</p><ol class="step-list"><li>Open <strong>Settings → End-effector</strong> (1).</li><li>Select <strong>Other</strong> in the end-effector menu (2).</li><li>Click <strong>Upload</strong> (3), choose <code>{file}</code> in the file picker, and confirm.</li><li>Click <strong>Apply</strong> (4). Check that the button changes to <strong>Applied</strong> and the values-differ warnings disappear.</li></ol><figure><a href="images/{slug}-desk.svg"><img src="images/{slug}-desk.svg" alt="Franka Desk: End-effector, Other, Upload and Apply circled"></a><figcaption>The configured {slug} assembly after Apply. The circles identify the controls used above. Click the image to enlarge.</figcaption></figure><p>Use the supplied file for the pictured assembly. Reopen the page to confirm the settings were saved.</p>'

def camera_setup(code):
    return '<h3>Install the ZED SDK</h3><p>If ZED SDK 5.1 is already installed, continue to the camera check below. Otherwise, download the 5.1 installer matching your Ubuntu and CUDA versions from the <a href="https://www.stereolabs.com/developers/release">Stereolabs downloads page</a>. Use 5.1 to match this repository’s Python API dependency.</p><p>Follow the <a href="https://docs.stereolabs.com/docs/development/zed-sdk/linux">Linux installation instructions</a>: install <code>zstd</code>, give the downloaded installer execute permission, then run it. Keep the camera tools and AI module installed; Cloak uses neural depth. Restart the workstation when installation is complete.</p><p>The <code>uv sync</code> command above installs the project’s Python camera API. Installing the SDK alone does not install it into the Cloak environment.</p><h3>Find the camera serial numbers</h3><p>Connect the wrist and external cameras to the workstation. Close any program currently using them, then run:</p>'+code('/usr/local/zed/tools/ZED_Explorer --all')+'<p>The output lists each camera’s model and <code>S/N</code>. Use the wrist camera’s S/N for <code>WRIST_CAMERA_ID</code> and the external camera’s S/N for <code>EXTERNAL_CAMERA_ID</code>. Enter only the digits, not the camera index or <code>/dev/video</code> path.</p><p>To confirm which view belongs to each camera, open ZED Explorer and select it from the camera menu:</p>'+code('/usr/local/zed/tools/ZED_Explorer')+'<p>Check the live image and note its serial number. If the two cameras are hard to distinguish, connect one at a time while no robot client is running. Close ZED Explorer before calibration or deployment so it releases the cameras. See <a href="https://support.stereolabs.com/articles/8431598864-how-can-i-get-the-serial-number-of-my-camera">Stereolabs’ serial-number instructions</a>.</p>'
